48	    ///
49	    /// Implementation is responsible for version check,
50	    /// and throw LOGICAL_ERROR in case of unsupported version.
51	    ///
52	    /// See also:
53	    /// - IMergeTreeIndex::getSerializedFileExtension()
54	    /// - IMergeTreeIndex::getDeserializedFormat()
55	    /// - MergeTreeDataMergerMutator::collectFilesToSkip()
56	    /// - MergeTreeDataMergerMutator::collectFilesForRenames()
57	    virtual void deserializeBinary(ReadBuffer & istr, MergeTreeIndexVersion version) = 0;
