151	    virtual MergeTreeIndexFormat getDeserializedFormat(const DataPartStoragePtr & data_part_storage, const std::string & relative_path_prefix) const
152	    {
153	        if (data_part_storage->exists(relative_path_prefix + ".idx"))
154	            return {1, ".idx"};
155	        return {0 /*unknown*/, ""};
156	    }
