170	    {
171	        throw Exception(ErrorCodes::NOT_IMPLEMENTED,
172	            "MergedCondition is not implemented for index of type {}", index.type);
173	    }
174	
175	    Names getColumnsRequiredForIndexCalc() const { return index.expression->getRequiredColumns(); }
176	
177	    const IndexDescription & index;
178	};
