21	void MergeTreeIndexFactory::registerCreator(const std::string & index_type, Creator creator)
22	{
23	    if (!creators.emplace(index_type, std::move(creator)).second)
24	        throw Exception("MergeTreeIndexFactory: the Index creator name '" + index_type + "' is not unique",
25	                        ErrorCodes::LOGICAL_ERROR);
26	}
27	void MergeTreeIndexFactory::registerValidator(const std::string & index_type, Validator validator)
28	{
29	    if (!validators.emplace(index_type, std::move(validator)).second)
30	        throw Exception("MergeTreeIndexFactory: the Index validator name '" + index_type + "' is not unique", ErrorCodes::LOGICAL_ERROR);
31	}
