34	MergeTreeIndexPtr MergeTreeIndexFactory::get(
35	    const IndexDescription & index) const
36	{
37	    auto it = creators.find(index.type);
38	    if (it == creators.end())
39	        throw Exception(
40	                "Unknown Index type '" + index.type + "'. Available index types: " +
41	                std::accumulate(creators.cbegin(), creators.cend(), std::string{},
42	                        [] (auto && left, const auto & right) -> std::string
43	                        {
44	                            if (left.empty())
45	                                return right.first;
46	                            else
47	                                return left + ", " + right.first;
48	                        }),
49	                ErrorCodes::INCORRECT_QUERY);
50	
51	    return it->second(index);
52	}
