63	void MergeTreeIndexFactory::validate(const IndexDescription & index, bool attach) const
64	{
65	    auto it = validators.find(index.type);
66	    if (it == validators.end())
67	        throw Exception(
68	            "Unknown Index type '" + index.type + "'. Available index types: "
69	                + std::accumulate(
70	                    validators.cbegin(),
71	                    validators.cend(),
72	                    std::string{},
73	                    [](auto && left, const auto & right) -> std::string
74	                    {
75	                        if (left.empty())
76	                            return right.first;
77	                        else
78	                            return left + ", " + right.first;
79	                    }),
80	            ErrorCodes::INCORRECT_QUERY);
81	
82	    it->second(index, attach);
83	}
